DELETE FROM ocp5_product_to_layout WHERE product_id IN (PRODUCT_IDS);
DELETE FROM ocp5_product_to_store WHERE product_id IN (PRODUCT_IDS);
DELETE FROM ocp5_product_to_category WHERE product_id IN (PRODUCT_IDS);
DELETE FROM ocp5_product_description WHERE product_id IN (PRODUCT_IDS);
DELETE FROM ocp5_seo_url WHERE `key` = 'product_id' AND value IN (PRODUCT_IDS);
DELETE FROM ocp5_product WHERE product_id IN (PRODUCT_IDS);
DELETE FROM ocp5_attribute_description
 WHERE attribute_id = ATTRIBUTE_ID AND language_id = 4;
