declare(strict_types=1);

const PATCH_ID = 'CONTENT-005_starter-decks-publish_20260810';
const PAYLOAD_SHA256 = 'ccebeb5deed546b59a653a38eb2ac5a4c7c7a22d489042cd5b0f2271648e8a89';
const PAYLOAD_B64 = '';

function out(string $key, string $value): void {
    echo $key . '=' . $value . PHP_EOL;
}

function require_true(bool $condition, string $message): void {
    if (!$condition) {
        throw new RuntimeException($message);
    }
}

function qi(string $name): string {
    return chr(96) . str_replace(chr(96), chr(96) . chr(96), $name) . chr(96);
}

function marks(int $count): string {
    require_true($count > 0, 'invalid_placeholder_count');
    return implode(',', array_fill(0, $count, '?'));
}

function stmt(mysqli $db, string $sql, array $params = []): mysqli_stmt {
    $statement = $db->prepare($sql);
    require_true($statement instanceof mysqli_stmt, 'prepare_failed: ' . $db->error);

    if ($params !== []) {
        $types = str_repeat('s', count($params));
        $arguments = [&$types];
        foreach ($params as $index => $value) {
            $params[$index] = $value;
            $arguments[] = &$params[$index];
        }
        require_true(call_user_func_array([$statement, 'bind_param'], $arguments), 'bind_failed: ' . $statement->error);
    }

    require_true($statement->execute(), 'execute_failed: ' . $statement->error);
    return $statement;
}

function rows(mysqli $db, string $sql, array $params = []): array {
    $statement = stmt($db, $sql, $params);
    $metadata = $statement->result_metadata();
    require_true($metadata instanceof mysqli_result, 'result_metadata_failed');

    $fields = $metadata->fetch_fields();
    $boundValues = [];
    $arguments = [];
    foreach ($fields as $index => $field) {
        $boundValues[$index] = null;
        $arguments[] = &$boundValues[$index];
    }
    require_true(call_user_func_array([$statement, 'bind_result'], $arguments), 'result_bind_failed: ' . $statement->error);

    $resultRows = [];
    while ($statement->fetch()) {
        $resultRow = [];
        foreach ($fields as $index => $field) {
            $resultRow[$field->name] = $boundValues[$index];
        }
        $resultRows[] = $resultRow;
    }
    return $resultRows;
}

function row(mysqli $db, string $sql, array $params = []): ?array {
    $found = rows($db, $sql, $params);
    require_true(count($found) <= 1, 'expected_one_row_got_' . count($found));
    return $found[0] ?? null;
}

function scalar(mysqli $db, string $sql, array $params = []): string {
    $found = row($db, $sql, $params);
    require_true($found !== null && count($found) === 1, 'scalar_query_failed');
    return (string)array_values($found)[0];
}

function table_exists(mysqli $db, string $table): void {
    stmt($db, 'SELECT 1 FROM ' . qi($table) . ' LIMIT 0');
}

function ids(array $rows, string $column): array {
    return array_map(static fn(array $value): int => (int)$value[$column], $rows);
}

function check_faqs(array $products): void {
    foreach ($products as $offset => $product) {
        $faq = 'prod-st' . (32 + $offset);
        $html = (string)$product['description'];
        require_true(substr_count($html, 'data-bs-faq-id="' . $faq . '"') === 1, 'faq_id_invalid_' . $faq);
        require_true(substr_count($html, 'class="bs-faq-item"') === 4, 'faq_items_invalid_' . $faq);
        require_true(substr_count($html, 'class="bs-faq-toggle"') === 4, 'faq_toggles_invalid_' . $faq);
        require_true(substr_count($html, 'class="bs-faq-panel"') === 4, 'faq_panels_invalid_' . $faq);
        require_true(substr_count($html, 'hidden=""') === 4, 'faq_hidden_invalid_' . $faq);
        for ($number = 1; $number <= 4; $number++) {
            $button = 'bs-faq-' . $faq . '-button-' . $number;
            $panel = 'bs-faq-' . $faq . '-panel-' . $number;
            require_true(substr_count($html, 'id="' . $button . '"') === 1, 'faq_button_invalid_' . $button);
            require_true(substr_count($html, 'id="' . $panel . '"') === 1, 'faq_panel_invalid_' . $panel);
            require_true(substr_count($html, 'aria-controls="' . $panel . '"') === 1, 'faq_controls_invalid_' . $panel);
            require_true(substr_count($html, 'aria-labelledby="' . $button . '"') === 1, 'faq_label_invalid_' . $button);
        }
    }
}

function write_prestate(array $data): string {
    $directory = getcwd() . DIRECTORY_SEPARATOR . '_patch_backups' . DIRECTORY_SEPARATOR
        . PATCH_ID . '-' . gmdate('Ymd-His');
    if (!is_dir($directory) && !mkdir($directory, 0750, true) && !is_dir($directory)) {
        throw new RuntimeException('backup_directory_create_failed');
    }

    $path = $directory . DIRECTORY_SEPARATOR . 'prestate.json';
    $json = json_encode($data, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR) . PHP_EOL;
    require_true(file_put_contents($path, $json, LOCK_EX) !== false, 'backup_write_failed');
    return $path;
}

$transaction = false;
$db = null;

try {
    require_true(PHP_SAPI === 'cli', 'cli_only');
    $args = array_slice($argv, 1);
    require_true(count($args) === 1 && in_array($args[0], ['--dry-run', '--apply'], true), 'usage: php ' . basename(__FILE__) . ' --dry-run|--apply');
    $dryRun = $args[0] === '--dry-run';

    $disabledFunctions = array_filter(array_map('trim', explode(',', (string)ini_get('disable_functions'))));
    if (function_exists('exec') && !in_array('exec', $disabledFunctions, true)) {
        $lintOutput = [];
        $lintStatus = 1;
        exec(escapeshellarg(PHP_BINARY) . ' -l ' . escapeshellarg(__FILE__), $lintOutput, $lintStatus);
        require_true($lintStatus === 0, 'php_lint_failed');
        out('php_lint', 'ok');
    } else {
        out('php_lint', 'skipped_exec_unavailable_php_parser_already_validated');
    }

    $json = base64_decode(PAYLOAD_B64, true);
    require_true($json !== false && hash('sha256', $json) === PAYLOAD_SHA256, 'payload_integrity_failed');
    $products = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
    require_true(is_array($products) && count($products) === 5, 'payload_product_count_invalid');

    $skus = ['OP-JP-ST32-STD', 'OP-JP-ST33-STD', 'OP-JP-ST34-STD', 'OP-JP-ST35-STD', 'OP-JP-ST36-STD'];
    $attributeOrder = [
        'Назва сету', 'Мова', 'Тип пакування', 'Кількість карток у колоді',
        'Стан', 'Виробник', 'Рік випуску', 'Додатковий вміст',
    ];
    foreach ($products as $index => $product) {
        require_true((string)($product['sku'] ?? '') === $skus[$index], 'payload_sku_invalid_' . $index);
        require_true(array_column($product['attributes'] ?? [], 'name') === $attributeOrder, 'payload_attribute_order_invalid_' . $skus[$index]);
        require_true(count($product['attributes']) === 8, 'payload_attribute_count_invalid_' . $skus[$index]);
    }
    check_faqs($products);

    require_true(is_file(getcwd() . DIRECTORY_SEPARATOR . 'config.php'), 'run_from_public_html_required');
    require getcwd() . DIRECTORY_SEPARATOR . 'config.php';
    foreach (['DB_HOSTNAME', 'DB_USERNAME', 'DB_PASSWORD', 'DB_DATABASE', 'DB_PORT', 'DB_PREFIX'] as $constant) {
        require_true(defined($constant), 'config_constant_missing_' . $constant);
    }
    require_true((string)DB_PREFIX === 'ocp5_', 'db_prefix_mismatch_expected_ocp5_');

    mysqli_report(MYSQLI_REPORT_ERROR | MYSQLI_REPORT_STRICT);
    $db = new mysqli((string)DB_HOSTNAME, (string)DB_USERNAME, (string)DB_PASSWORD, (string)DB_DATABASE, (int)DB_PORT);
    $db->set_charset('utf8mb4');
    $prefix = (string)DB_PREFIX;
    $t = static fn(string $name): string => qi($prefix . $name);

    foreach ([
        'product', 'product_description', 'product_to_category', 'product_to_store',
        'product_to_layout', 'product_attribute', 'product_related', 'seo_url',
        'attribute', 'attribute_description', 'manufacturer', 'stock_status'
    ] as $name) {
        table_exists($db, $prefix . $name);
    }

    $op16 = row(
        $db,
        'SELECT product_id, model, sku, quantity, stock_status_id, status, date_available, tax_class_id, shipping, manufacturer_id, sort_order, subtract, minimum, price FROM ' . $t('product') . ' WHERE product_id = ? AND model = ?',
        ['107', 'OP-JP-OP16-BBX']
    );
    require_true($op16 !== null, 'op16_template_missing');
    require_true(
        (int)$op16['quantity'] === 0 && (int)$op16['stock_status_id'] === 8 &&
        (int)$op16['status'] === 1 && (string)$op16['date_available'] === '2026-07-08' &&
        (int)$op16['tax_class_id'] === 0 && (int)$op16['shipping'] === 1 &&
        (int)$op16['manufacturer_id'] === 12 && (int)$op16['sort_order'] === 0 &&
        (int)$op16['subtract'] === 1 && (int)$op16['minimum'] === 1 &&
        (string)$op16['price'] === '5000.0000' && $op16['sku'] === null,
        'op16_template_drift'
    );

    $descriptionRows = rows($db, 'SELECT language_id FROM ' . $t('product_description') . ' WHERE product_id = ?', ['107']);
    require_true(count($descriptionRows) === 1 && (int)$descriptionRows[0]['language_id'] === 4, 'op16_language_drift');

    $categories = rows($db, 'SELECT category_id FROM ' . $t('product_to_category') . ' WHERE product_id = ? ORDER BY category_id', ['107']);
    $stores = rows($db, 'SELECT store_id FROM ' . $t('product_to_store') . ' WHERE product_id = ? ORDER BY store_id', ['107']);
    $layouts = rows($db, 'SELECT store_id, layout_id FROM ' . $t('product_to_layout') . ' WHERE product_id = ?', ['107']);
    require_true(ids($categories, 'category_id') === [60, 68], 'op16_category_drift');
    require_true(ids($stores, 'store_id') === [0], 'op16_store_drift');
    require_true($layouts === [], 'op16_layout_drift');

    $key = qi('key');
    $op16Seo = row(
        $db,
        'SELECT store_id, language_id, ' . $key . ' AS seo_key, value, keyword, sort_order FROM ' . $t('seo_url') . ' WHERE ' . $key . ' = ? AND value = ?',
        ['product_id', '107']
    );
    require_true(
        $op16Seo !== null && (int)$op16Seo['store_id'] === 0 &&
        (int)$op16Seo['language_id'] === 4 &&
        (string)$op16Seo['keyword'] === 'One-Piece-OP-16-The-Time-of-Battle-Booster-Box-JP' &&
        (int)$op16Seo['sort_order'] === 0,
        'op16_seo_drift'
    );

    $bandai = row($db, 'SELECT name FROM ' . $t('manufacturer') . ' WHERE manufacturer_id = ?', ['12']);
    $preorder = row($db, 'SELECT name FROM ' . $t('stock_status') . ' WHERE stock_status_id = ? AND language_id = ?', ['8', '4']);
    require_true($bandai !== null && (string)$bandai['name'] === 'Bandai', 'bandai_drift');
    require_true($preorder !== null && (string)$preorder['name'] === 'Передзамовлення', 'preorder_status_drift');

    $existing = [
        'Назва сету' => [13, 1], 'Мова' => [12, 2], 'Тип пакування' => [21, 3],
        'Додатковий вміст' => [24, 4], 'Стан' => [17, 6],
        'Виробник' => [20, 8], 'Рік випуску' => [14, 9],
    ];
    $attributeRows = rows(
        $db,
        'SELECT a.attribute_id, a.attribute_group_id, a.sort_order, ad.name FROM ' . $t('attribute') . ' a INNER JOIN ' . $t('attribute_description') . ' ad ON ad.attribute_id = a.attribute_id WHERE ad.language_id = ? AND ad.name IN (' . marks(7) . ')',
        array_merge(['4'], array_keys($existing))
    );
    require_true(count($attributeRows) === 7, 'existing_attribute_count_drift');
    $attributeIds = [];
    foreach ($attributeRows as $attribute) {
        $name = (string)$attribute['name'];
        require_true(isset($existing[$name]), 'unexpected_attribute_' . $name);
        require_true((int)$attribute['attribute_id'] === $existing[$name][0] && (int)$attribute['attribute_group_id'] === 7 && (int)$attribute['sort_order'] === $existing[$name][1], 'attribute_drift_' . $name);
        $attributeIds[$name] = (int)$attribute['attribute_id'];
    }

    $newAttribute = rows(
        $db,
        'SELECT a.attribute_id FROM ' . $t('attribute') . ' a INNER JOIN ' . $t('attribute_description') . ' ad ON ad.attribute_id = a.attribute_id WHERE ad.language_id = ? AND ad.name = ?',
        ['4', 'Кількість карток у колоді']
    );

    $existingProducts = rows(
        $db,
        'SELECT product_id, model, sku FROM ' . $t('product') . ' WHERE model IN (' . marks(5) . ') OR sku IN (' . marks(5) . ')',
        array_merge($skus, $skus)
    );
    if ($existingProducts !== []) {
        $existingIds = [];
        foreach ($existingProducts as $product) {
            $model = (string)$product['model'];
            require_true(in_array($model, $skus, true) && (string)$product['sku'] === $model, 'partial_or_conflicting_products_exist');
            $existingIds[$model] = (int)$product['product_id'];
        }
        require_true(count($existingIds) === 5, 'partial_product_set_exists_abort');
        $existingIdList = array_map(static fn(int $id): string => (string)$id, array_values($existingIds));
        require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('product_description') . ' WHERE product_id IN (' . marks(5) . ') AND language_id = ?', array_merge($existingIdList, ['4'])) === 5, 'existing_product_set_description_incomplete');
        require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('product_attribute') . ' WHERE product_id IN (' . marks(5) . ') AND language_id = ?', array_merge($existingIdList, ['4'])) === 40, 'existing_product_set_attribute_incomplete');
        require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('seo_url') . ' WHERE ' . $key . ' = ? AND value IN (' . marks(5) . ')', array_merge(['product_id'], $existingIdList)) === 5, 'existing_product_set_seo_incomplete');
        require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('product_related') . ' WHERE product_id IN (' . marks(5) . ')', $existingIdList) === 10, 'existing_product_set_related_incomplete');
        out('already_applied', 'yes');
        foreach ($skus as $index => $sku) {
            out('product_id_' . $sku, (string)$existingIds[$sku]);
            out('url_' . $sku, 'https://boostershop.website/product/' . $products[$index]['seo']);
        }
        out('self_delete', $dryRun ? 'not_requested_dry_run' : (@unlink(__FILE__) ? 'ok' : 'failed'));
        exit(0);
    }
    require_true($newAttribute === [], 'new_attribute_already_exists_abort');

    $keywords = array_column($products, 'seo');
    require_true(rows($db, 'SELECT seo_url_id FROM ' . $t('seo_url') . ' WHERE keyword IN (' . marks(5) . ')', $keywords) === [], 'seo_keyword_collision');
    foreach ($products as $index => $product) {
        $faq = 'prod-st' . (32 + $index);
        require_true(rows($db, 'SELECT product_id FROM ' . $t('product_description') . ' WHERE description LIKE ?', ['%data-bs-faq-id="' . $faq . '"%']) === [], 'faq_id_collision_' . $faq);
    }

    $source = row($db, 'SELECT * FROM ' . $t('product') . ' WHERE product_id = ?', ['107']);
    require_true($source !== null, 'op16_source_row_missing');
    $columns = rows($db, 'SHOW COLUMNS FROM ' . $t('product'));
    $fields = array_map(static fn(array $column): string => (string)$column['Field'], $columns);
    foreach (['product_id', 'model', 'sku', 'price', 'image', 'quantity', 'stock_status_id', 'manufacturer_id', 'shipping', 'tax_class_id', 'date_available', 'subtract', 'minimum', 'sort_order', 'status'] as $field) {
        require_true(in_array($field, $fields, true), 'product_column_missing_' . $field);
    }
    foreach (['ean', 'jan', 'isbn', 'upc', 'mpn', 'location'] as $field) {
        if (in_array($field, $fields, true)) {
            require_true($source[$field] === null || trim((string)$source[$field]) === '', 'op16_' . $field . '_must_be_empty');
        }
    }

    $copyFields = [
        'quantity', 'stock_status_id', 'manufacturer_id', 'shipping', 'tax_class_id',
        'date_available', 'weight_class_id', 'length_class_id', 'subtract', 'minimum',
        'sort_order', 'status',
    ];
    $fixedValues = [
        'model' => '', 'sku' => '', 'upc' => '', 'ean' => '', 'jan' => '', 'isbn' => '',
        'mpn' => '', 'location' => '', 'image' => '', 'price' => '700.0000', 'points' => '0',
        'weight' => '0', 'length' => '0', 'width' => '0', 'height' => '0', 'viewed' => '0',
        'rating' => '0', 'master_id' => '0', 'date_added' => gmdate('Y-m-d H:i:s'),
        'date_modified' => gmdate('Y-m-d H:i:s'),
    ];
    $handledFields = array_fill_keys(array_merge($copyFields, array_keys($fixedValues)), true);
    foreach ($columns as $column) {
        $field = (string)$column['Field'];
        if ($field === 'product_id' || isset($handledFields[$field])) {
            continue;
        }
        require_true(
            (string)$column['Null'] === 'YES' || $column['Default'] !== null || stripos((string)$column['Extra'], 'auto_increment') !== false,
            'unhandled_required_product_column_' . $field
        );
    }

    $backup = write_prestate([
        'patch_id' => PATCH_ID, 'time_utc' => gmdate('c'), 'mode' => $dryRun ? 'dry-run' : 'apply',
        'db_prefix' => $prefix, 'op16_template' => $op16, 'categories' => $categories,
        'stores' => $stores, 'layouts' => $layouts, 'op16_seo' => $op16Seo,
        'products' => array_map(static fn(array $product): array => ['sku' => $product['sku'], 'seo' => $product['seo'], 'name' => $product['name']], $products),
    ]);
    out('cwd', (string)getcwd());
    out('time_utc', gmdate('c'));
    out('backup_prestate', $backup);
    out('mode', $dryRun ? 'dry-run' : 'apply');
    out('discovery', 'ok');

    if ($dryRun) {
        out('dry_run', 'ok');
        out('done', 'ok');
        exit(0);
    }

    $db->begin_transaction();
    $transaction = true;

    stmt($db, 'INSERT INTO ' . $t('attribute') . ' (attribute_group_id, sort_order) VALUES (?, ?)', ['7', '5']);
    $newAttributeId = (int)$db->insert_id;
    require_true($newAttributeId > 0, 'new_attribute_insert_failed');
    stmt($db, 'INSERT INTO ' . $t('attribute_description') . ' (attribute_id, language_id, name) VALUES (?, ?, ?)', [(string)$newAttributeId, '4', 'Кількість карток у колоді']);
    $attributeIds['Кількість карток у колоді'] = $newAttributeId;

    $insertFields = array_values(array_filter($fields, static fn(string $field): bool => isset($handledFields[$field])));
    $baseValues = [];
    foreach ($copyFields as $field) {
        if (in_array($field, $fields, true)) {
            require_true(array_key_exists($field, $source), 'template_field_missing_' . $field);
            $baseValues[$field] = $source[$field];
        }
    }
    foreach ($fixedValues as $field => $value) {
        if (in_array($field, $fields, true)) {
            $baseValues[$field] = $value;
        }
    }
    $insertSql = 'INSERT INTO ' . $t('product') . ' (' . implode(',', array_map('qi', $insertFields)) . ') VALUES (' . marks(count($insertFields)) . ')';
    $productIds = [];

    foreach ($products as $product) {
        $baseValues['model'] = $product['sku'];
        $baseValues['sku'] = $product['sku'];
        $values = array_map(static fn(string $field) => $baseValues[$field], $insertFields);
        stmt($db, $insertSql, $values);
        $productId = (int)$db->insert_id;
        require_true($productId > 0, 'product_insert_failed_' . $product['sku']);
        $productIds[$product['sku']] = $productId;

        stmt(
            $db,
            'INSERT INTO ' . $t('product_description') . ' (product_id, language_id, name, description, tag, meta_title, meta_description, meta_keyword) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
            [(string)$productId, '4', $product['name'], $product['description'], '', $product['meta_title'], $product['meta_description'], $product['meta_keyword']]
        );
        foreach ($categories as $category) {
            stmt($db, 'INSERT INTO ' . $t('product_to_category') . ' (product_id, category_id) VALUES (?, ?)', [(string)$productId, (string)$category['category_id']]);
        }
        foreach ($stores as $store) {
            stmt($db, 'INSERT INTO ' . $t('product_to_store') . ' (product_id, store_id) VALUES (?, ?)', [(string)$productId, (string)$store['store_id']]);
        }
        foreach ($layouts as $layout) {
            stmt($db, 'INSERT INTO ' . $t('product_to_layout') . ' (product_id, store_id, layout_id) VALUES (?, ?, ?)', [(string)$productId, (string)$layout['store_id'], (string)$layout['layout_id']]);
        }
        foreach ($product['attributes'] as $attribute) {
            $name = (string)$attribute['name'];
            require_true(isset($attributeIds[$name]), 'attribute_mapping_missing_' . $name);
            stmt($db, 'INSERT INTO ' . $t('product_attribute') . ' (product_id, attribute_id, language_id, text) VALUES (?, ?, ?, ?)', [(string)$productId, (string)$attributeIds[$name], '4', (string)$attribute['value']]);
        }
        stmt($db, 'INSERT INTO ' . $t('seo_url') . ' (store_id, language_id, ' . $key . ', value, keyword, sort_order) VALUES (?, ?, ?, ?, ?, ?)', ['0', '4', 'product_id', (string)$productId, $product['seo'], '0']);
    }

    foreach ($skus as $index => $sku) {
        $next = $skus[($index + 1) % count($skus)];
        stmt($db, 'INSERT INTO ' . $t('product_related') . ' (product_id, related_id) VALUES (?, ?)', [(string)$productIds[$sku], (string)$productIds[$next]]);
        stmt($db, 'INSERT INTO ' . $t('product_related') . ' (product_id, related_id) VALUES (?, ?)', [(string)$productIds[$sku], '107']);
    }

    $newIds = array_map(static fn(int $id): string => (string)$id, array_values($productIds));
    require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('product') . ' WHERE product_id IN (' . marks(5) . ')', $newIds) === 5, 'verify_product_count_failed');
    require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('product_description') . ' WHERE product_id IN (' . marks(5) . ') AND language_id = ?', array_merge($newIds, ['4'])) === 5, 'verify_description_count_failed');
    require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('product_attribute') . ' WHERE product_id IN (' . marks(5) . ') AND language_id = ?', array_merge($newIds, ['4'])) === 40, 'verify_attribute_count_failed');
    require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('product_related') . ' WHERE product_id IN (' . marks(5) . ')', $newIds) === 10, 'verify_related_count_failed');
    require_true((int)scalar($db, 'SELECT COUNT(*) FROM ' . $t('seo_url') . ' WHERE ' . $key . ' = ? AND value IN (' . marks(5) . ')', array_merge(['product_id'], $newIds)) === 5, 'verify_seo_count_failed');

    $db->commit();
    $transaction = false;

    out('new_attribute_id', (string)$newAttributeId);
    out('new_attribute_created', 'yes');
    foreach ($skus as $index => $sku) {
        out('product_id_' . $sku, (string)$productIds[$sku]);
        out('url_' . $sku, 'https://boostershop.website/product/' . $products[$index]['seo']);
    }
    out('rollback_product_ids_csv', implode(',', $newIds));
    out('changed_tables', 'ocp5_attribute,ocp5_attribute_description,ocp5_product,ocp5_product_description,ocp5_product_to_category,ocp5_product_to_store,ocp5_product_attribute,ocp5_product_related,ocp5_seo_url');
    out('done', 'ok');
    out('self_delete', @unlink(__FILE__) ? 'ok' : 'failed');
    exit(0);
} catch (Throwable $error) {
    if ($transaction && $db instanceof mysqli) {
        $db->rollback();
        out('transaction', 'rolled_back');
    }
    out('done', 'failed');
    fwrite(STDERR, PATCH_ID . ': ' . $error->getMessage() . PHP_EOL);
    exit(1);
}
